from collections import deque
def comps(g, bg):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<R and 0<=ny<C and not seen[nx][ny] and g[nx][ny]!=bg:
                            seen[nx][ny]=True; q.append((nx,ny))
                out.append((col,len(cells),cells))
    return out
