def variants(cells):
    pts=[(r,c) for r,c in cells]
    outs=set()
    cur=pts
    for _ in range(4):
        for ref in [False,True]:
            cc=[(r,-c) if ref else (r,c) for r,c in cur]
            m=min(r for r,c in cc),min(c for r,c in cc)
            outs.add(tuple(sorted((r-m[0],c-m[1]) for r,c in cc)))
        cur=[(c,-r) for r,c in cur]
    return outs
def dup_groups(g,bg,exact_only=True):
    cs=comps(g,bg); groups=[]
    for i,a in enumerate(cs):
        for b in cs[i+1:]:
            va=variants(a[2]); vb=variants(b[2])
            if (va & vb): groups.append((a,b))
    # union-find groups
    parent=list(range(len(cs)))
    def find(x):
        while parent[x]!=x: x=parent[x]
        return x
    for a,b in groups:
        ia,ib=cs.index(a),cs.index(b)
        parent[find(ia)]=find(ib)
    from collections import defaultdict
    gd=defaultdict(list)
    for i in range(len(cs)): gd[find(i)].append(i)
    return cs,gd,groups
